package net.officefloor.hq.app;

import net.officefloor.server.http.HttpHeader;
import net.officefloor.server.http.ServerHttpConnection;

/** The signed-in user of a request: the name the front end sends in the X-User header. */
public final class CurrentUser {
    public static final String HEADER = "X-User";

    private CurrentUser() {
    }

    /** The trimmed name, refused when blank. A step takes the {@link ServerHttpConnection} and
     *  passes it here (header names are matched ignoring case, as browsers send them lower-case). */
    public static String require(ServerHttpConnection connection) throws BadRequestException {
        String name = "";
        for (HttpHeader header : connection.getRequest().getHeaders()) {
            if (HEADER.equalsIgnoreCase(header.getName())) {
                name = header.getValue() == null ? "" : header.getValue().trim();
                break;
            }
        }
        if (name.isEmpty()) {
            throw new BadRequestException("not signed in");
        }
        return name;
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.io.Resource;
import org.springframework.web.servlet.config.annotation.ResourceHandlerRegistry;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;
import org.springframework.web.servlet.resource.PathResourceResolver;

/**
 * Serve the SPA from static/ with a deep-link fallback: an unknown, non-API path returns
 * index.html so a browser refresh on a client route works. OfficeFloor REST routes and Spring
 * endpoints are matched first; only unmatched, non-{@code api/} paths fall through to the SPA.
 * TODO: confirm the API path prefix used by the OfficeFloor routes ("api/" assumed here).
 */
@Configuration
public class SpaConfig implements WebMvcConfigurer {

    @Override
    public void addResourceHandlers(ResourceHandlerRegistry registry) {
        registry.addResourceHandler("/**")
                .addResourceLocations("classpath:/static/")
                .resourceChain(true)
                .addResolver(new PathResourceResolver() {
                    @Override
                    protected Resource getResource(String resourcePath, Resource location) throws IOException {
                        if (resourcePath.startsWith("api/")) {
                            return null; // let the API handle / 404 it
                        }
                        Resource requested = location.createRelative(resourcePath);
                        return (requested.exists() && requested.isReadable())
                                ? requested
                                : location.createRelative("index.html");
                    }
                });
    }
}
package net.officefloor.hq.app.settings;

import java.util.Set;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the role form: a user name (no spaces) and a role, clerk or steward. */
public class ValidateRole {
    private static final Set<String> ROLES = Set.of(SettingsRepository.CLERK, SettingsRepository.STEWARD);

    public void validate(@RequestBody RoleRequest request, Out<Role> role) throws BadRequestException {
        String user = request == null || request.user() == null ? "" : request.user().trim();
        String name = request == null || request.role() == null ? "" : request.role().trim();
        if (user.isEmpty()) {
            throw new BadRequestException("user is required");
        }
        if (user.chars().anyMatch(Character::isWhitespace)) {
            throw new BadRequestException("user must not contain spaces");
        }
        if (!ROLES.contains(name)) {
            throw new BadRequestException("role must be clerk or steward");
        }
        role.set(new Role(user, name));
    }
}

