# Load a sheet by id: made (empty) the first time the id is used, re-read from the store after.
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheet
== {sheetId}/bulk-open.POST.yml
# Open the selected claims together: each DRAFT that may be opened is opened and numbered in list order
# (people in the order they were added, each person's claims newest first); every other is left as it
# is. Answers how many were opened and how many refused.
open:
  class: net.officefloor.hq.app.claim.BulkOpenClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithBulkOpen
== {sheetId}/bulk-settle.POST.yml
# Settle the selected claims together: each is settled in list order (people in the order they were
# added, each person's claims newest first) by the rules of a single settle (a claim sent to PENDING
# counts as settled); every other is left as it is. Answers how many were settled and how many refused.
settle:
  class: net.officefloor.hq.app.claim.BulkSettleClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithBulkSettle
== {sheetId}/periods.POST.yml
# Add a period: a name unique on the sheet and a from- and to-date (inclusive, from on or before
# to) that overlap no other period of the sheet.
validate:
  class: net.officefloor.hq.app.period.ValidatePeriod
  next: save
save:
  class: net.officefloor.hq.app.period.SavePeriod
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithPeriod
